"""Google Agent Development Kit (ADK) integration — BETA.

Maps ADK execution events to PRISMtrace traces via the existing
``POST /api/traces`` endpoint. No new backend endpoints are introduced.

Status: BETA.

What this currently captures (real, working for ADK 1.x ``LlmAgent`` flows
and multi-agent transfer-to-agent setups):

- Per-turn model call: input messages, output message, model id, latency,
  token counts, session_id.
- Tool calls when surfaced via ADK's ``after_tool_callback``. Real wall-
  clock latency is captured when ``before_tool_callback`` is also wired
  to ``adapter.before_tool``; otherwise the trace stamps ``latency_ms=0``
  and ``tool_latency_unavailable=True`` so downstream readers can tell.
- Error traces via ``record_model_error`` / ``record_tool_error`` /
  ``record_runner_error``. These post the same trace shape with
  ``status=error``, an ``error_type``, and a sanitized ``error_message``
  in metadata. Customer-controlled strings are scrubbed of known secret
  patterns before they leave the process.
- **Sub-agent hierarchy metadata** on every trace:
  ``agent_name``, ``agent_id``, ``parent_agent_id``, ``agent_path``
  (root → leaf list of agent names), ``root_agent_name``, ``node_id``,
  ``parent_node_id``, ``invocation_id``, ``step_order``,
  ``adk_event_type``. The trajectory assembler reads ``step_order`` for
  ordering and stamps the rest onto each trajectory step's metadata so
  downstream consumers can reconstruct the agent tree.

What is NOT yet captured (deliberately left as gaps so we don't overstate):

- ADK-specific event types that aren't model / tool / agent / error
  boundaries (e.g. memory reads, planner events). Silently ignored
  rather than mis-mapped.
- Streaming sub-events — the per-turn capture happens at the end of each
  agent step, not per token.

Usage:

    from prismtrace import PRISMtraceADKAdapter
    from google.adk.agents import LlmAgent

    adapter = PRISMtraceADKAdapter(
        api_key="pt-sk-...",
        project_id="<uuid>",
        agent_name="my-adk-agent",  # appears in Agent Runs as the trajectory name
    )

    specialist = LlmAgent(
        name="rate_specialist",
        model="gemini-3.6-flash",
        instruction="...",
        tools=[lookup_rate],
        before_model_callback=adapter.before_model,
        after_model_callback=adapter.after_model,
        before_tool_callback=adapter.before_tool,
        after_tool_callback=adapter.after_tool,
        before_agent_callback=adapter.before_agent,
        after_agent_callback=adapter.after_agent,
    )

    root = LlmAgent(
        name="loan_assistant",
        model="gemini-3.6-flash",
        instruction="...",
        sub_agents=[specialist],
        before_model_callback=adapter.before_model,
        after_model_callback=adapter.after_model,
        before_tool_callback=adapter.before_tool,
        after_tool_callback=adapter.after_tool,
        before_agent_callback=adapter.before_agent,
        after_agent_callback=adapter.after_agent,
    )

The label string written into every trace's model field includes
"google-adk" so the server architecture extractor renders the run as
framework=google_adk. Hierarchy metadata is in ``trace.metadata`` (jsonb).
"""

from __future__ import annotations
from ._config import DEFAULT_HOST, resolve_host
from ._session import resolve_session

import hashlib
import re
import threading
import time
import uuid
from collections import OrderedDict
from typing import Any, Optional

import httpx


# Span-name token the server architecture extractor uses to detect ADK.
# Do NOT rename without updating backend/app/services/architecture_extractor.py.
_FRAMEWORK_TAG = "google-adk"

_DEFAULT_ENDPOINT = DEFAULT_HOST

# Bounded pending-event store. ADK is supposed to call after_model after
# every before_model, but if a callback path errors before after_model fires
# (network error, exception in the model call), the pending entry would
# leak. We cap the dict and evict the oldest entries on overflow.
_PENDING_MAX = 256

# Cap on serialized error message length — keeps tracebacks from blowing
# up the metadata jsonb. Applied after secret scrubbing.
_ERROR_MESSAGE_MAX = 4000


# Secret patterns scrubbed from any string that flows into trace metadata.
# Order is intentional — broader patterns (Authorization headers, generic
# api_key=...) come last so the precise key-prefix patterns get a chance
# to claim their characters first.
_SECRET_PATTERNS: tuple[tuple[re.Pattern[str], str], ...] = (
    # PRISMtrace keys.
    (re.compile(r"pt-sk-[A-Za-z0-9_\-]{8,}"), "[REDACTED]"),
    # OpenAI keys (sk-proj-… and sk-…).
    (re.compile(r"sk-(?:proj|svcacct|admin)-[A-Za-z0-9_\-]{16,}"), "[REDACTED]"),
    (re.compile(r"sk-[A-Za-z0-9_\-]{32,}"), "[REDACTED]"),
    # Anthropic keys.
    (re.compile(r"sk-ant-[A-Za-z0-9_\-]{20,}"), "[REDACTED]"),
    # Google API keys (AIza-prefixed, 35+ alnum chars in practice).
    (re.compile(r"AIza[A-Za-z0-9_\-]{20,}"), "[REDACTED]"),
    # Env-var-style leaks: PRISMTRACE_API_KEY=… / GOOGLE_API_KEY=… / etc.
    (
        re.compile(
            r"(?i)\b(PRISMTRACE_API_KEY|GOOGLE_API_KEY|ANTHROPIC_API_KEY|OPENAI_API_KEY|AZURE_OPENAI_API_KEY)\s*=\s*\S+"
        ),
        r"\1=[REDACTED]",
    ),
    # Authorization: Bearer <token>
    (
        re.compile(r"(?i)(authorization\s*[:=]\s*bearer\s+)\S+"),
        r"\1[REDACTED]",
    ),
    # x-api-key / X-Api-Key headers.
    (
        re.compile(r"(?i)(x-api-key\s*[:=]\s*)\S+"),
        r"\1[REDACTED]",
    ),
    # Generic api_key=… / api-key: … (last, so the prefix-specific
    # patterns above can win when they overlap).
    (
        re.compile(r"(?i)(\bapi[_\-]?key\s*[:=]\s*[\"']?)[A-Za-z0-9_\-]{8,}"),
        r"\1[REDACTED]",
    ),
)


def _scrub_secrets(text: Any) -> str:
    """Redact known secret patterns from ``text``.

    Stringifies whatever is passed and applies the secret patterns above
    in order. Length-capped at ``_ERROR_MESSAGE_MAX`` so a malicious or
    accidental megabyte traceback can't bloat the metadata payload.
    """
    if text is None:
        return ""
    out = str(text)
    for pattern, repl in _SECRET_PATTERNS:
        out = pattern.sub(repl, out)
    if len(out) > _ERROR_MESSAGE_MAX:
        out = out[: _ERROR_MESSAGE_MAX - 1] + "…"
    return out


def _tool_pending_key(tool: Any, tool_context: Any) -> Any:
    """Build a key for the ``_pending`` map that pairs before_tool with after_tool.

    Prefer the per-call tool_context identity (each ADK tool invocation
    gets a fresh context), fall back to the tool object identity. Tagged
    with a ``"tool"`` discriminator so the namespace is distinct from
    model keys, which use raw ``id(...)``.
    """
    if tool_context is not None:
        return ("tool", id(tool_context))
    if tool is not None:
        return ("tool", id(tool))
    return ("tool", None)



class PRISMtraceADKAdapter:
    """Adapter that turns ADK callback hooks into PRISMtrace traces.

    Designed to be passed in as ``before_model_callback`` /
    ``after_model_callback`` / ``after_tool_callback`` /
    ``before_agent_callback`` / ``after_agent_callback`` on ADK agents.
    The agent callbacks are optional — they are only used to bound
    the per-invocation step counter and to clean stale pending entries.

    This class is intentionally schema-light: it accepts whatever ADK
    passes and best-effort extracts the fields PRISMtrace needs. If ADK
    changes its callback signatures, traces will still post — they just
    won't include the missing fields.
    """

    def __init__(
        self,
        api_key: str,
        project_id: str,
        agent_name: str = f"{_FRAMEWORK_TAG}-agent",
        endpoint: Optional[str] = None,
        session_id: Optional[str] = None,
        timeout: int = 10,
    ) -> None:
        self.api_key = api_key
        self.project_id = project_id
        self.agent_name = agent_name
        self.endpoint = resolve_host(endpoint)
        # Seconds per POST; the SDK fails open, so this bounds silent loss
        # against a slow backend (KAN-47). Same argument the voice tracer takes.
        self.timeout = timeout
        # An explicit id wins; otherwise the session is read from the ambient
        # context when an invocation starts. The uuid is the last resort, so an
        # adapter used outside any session behaves as it did before.
        self._explicit_session_id = (session_id or "").strip() or None
        self._fallback_session_id = str(uuid.uuid4())

        # Pending bookkeeping for before/after pairing. Bounded — oldest
        # entry is evicted on overflow with a single warning print.
        self._pending: "OrderedDict[Any, dict]" = OrderedDict()
        # Monotonic per-invocation step counters so trajectory_steps order
        # honors ADK execution order even across nested sub-agents.
        self._step_counters: dict[str, int] = {}
        # Session resolved once per ADK invocation and reused for every trace
        # in it. ADK drives callbacks from asyncio but runs tools in a
        # threadpool, and a contextvar does not follow a plain thread, so a
        # tool callback must not re-resolve and find nothing in scope.
        self._invocation_sessions: dict[str, str] = {}
        self._closed = False
        # Single lock guards both. ADK runs in asyncio but tools may run in
        # a threadpool, so callbacks can race.
        self._lock = threading.Lock()

        self._http = httpx.Client(
            headers={
                "X-PRISMtrace-Key": api_key,
                "Content-Type": "application/json",
            },
            timeout=timeout,
        )

    # ------------------------------------------------------------------
    # Session identity
    # ------------------------------------------------------------------

    @property
    def session_id(self) -> str:
        """The session a trace emitted right now would carry."""
        return resolve_session(self._explicit_session_id, self._fallback_session_id)

    @session_id.setter
    def session_id(self, value: "Optional[str]") -> None:
        self._explicit_session_id = (value or "").strip() or None

    def _session_for(self, invocation_id: str) -> str:
        """The session for one ADK invocation, resolved once and then reused."""
        if not invocation_id:
            return self.session_id
        with self._lock:
            cached = self._invocation_sessions.get(invocation_id)
            if cached is None:
                cached = self.session_id
                self._invocation_sessions[invocation_id] = cached
            return cached

    # ------------------------------------------------------------------
    # ADK callback hooks
    # ------------------------------------------------------------------

    def before_agent(self, callback_context: Any = None, **kwargs: Any) -> None:
        """Touch the per-invocation step counter so it exists at agent entry.

        Optional hook. Used only to seed the counter for an invocation —
        we do NOT post a trace for agent boundaries (that would create
        empty traces with no model/tool data). The agent path is captured
        on every model/tool trace anyway, which is sufficient to
        reconstruct the hierarchy server-side.
        """
        ctx = self._extract_agent_context(callback_context)
        invocation_id = ctx.get("invocation_id") or ""
        with self._lock:
            self._step_counters.setdefault(invocation_id, 0)

    def after_agent(self, callback_context: Any = None, **kwargs: Any) -> None:
        """Clean up the per-invocation counter once the root agent finishes.

        We can't reliably tell from the callback alone whether this is the
        root or a sub-agent, so we only purge when the agent path has
        length 1 (i.e., this is the root). Sub-agent boundaries leave the
        counter alive so subsequent siblings keep monotonic ordering.
        """
        ctx = self._extract_agent_context(callback_context)
        if len(ctx.get("agent_path") or []) > 1:
            return
        invocation_id = ctx.get("invocation_id") or ""
        with self._lock:
            self._step_counters.pop(invocation_id, None)
            self._invocation_sessions.pop(invocation_id, None)
            # Also evict any pending entries whose invocation matches —
            # these are leaks (after_model never fired for them).
            for key in [k for k, v in self._pending.items() if v.get("invocation_id") == invocation_id]:
                self._pending.pop(key, None)

    def before_model(self, callback_context: Any = None, llm_request: Any = None, **kwargs: Any) -> None:
        """Stamp a start timestamp; we resolve the call on the matching after_model.

        Pairing key: ADK constructs a FRESH ``CallbackContext`` for each
        callback and does not pass ``llm_request`` to
        ``after_model_callback`` (verified in 1.0.0 and 2.8.0,
        ``base_llm_flow.py``), so no object identity survives from before
        to after. ``(invocation_id, agent_name)`` does — and within one
        invocation a given agent's model calls are strictly sequential,
        so a single slot per key suffices. A second before_model on the
        same key overwrites the first (e.g. ADK live flows fire screening
        before-callbacks with no matching after).
        """
        ctx = self._extract_agent_context(callback_context)
        key = self._model_pending_key(ctx)
        with self._lock:
            # Bound the dict — if we're at cap, drop the oldest entry.
            if len(self._pending) >= _PENDING_MAX:
                evicted_key, _ = self._pending.popitem(last=False)
                print(f"[prismtrace adk] pending overflow; evicted oldest entry id={evicted_key}")
            self._pending[key] = {
                "started_at": time.time(),
                "input_messages": self._extract_input_messages(llm_request, callback_context),
                "model": self._extract_model(llm_request),
                "agent_ctx": ctx,
                "invocation_id": ctx.get("invocation_id") or "",
            }

    def after_model(self, callback_context: Any = None, llm_response: Any = None, llm_request: Any = None, **kwargs: Any) -> None:
        """Resolve a model call and POST the trace.

        ``llm_request`` is accepted for backward compatibility with
        manual callers but real ADK never passes it here — the pending
        entry is looked up by ``(invocation_id, agent_name)``.
        """
        ctx = self._extract_agent_context(callback_context)
        key = self._model_pending_key(ctx)
        with self._lock:
            pending = self._pending.pop(key, None)
        if pending is None:
            # before_model was never observed; build a degraded entry so
            # the trace still posts rather than being silently dropped.
            # Keep the real invocation_id — blanking it would make the
            # step counter run on a different key from tool steps and
            # collide step_order values within the Agent Run.
            pending = {
                "started_at": time.time(),
                "input_messages": self._extract_input_messages(llm_request, callback_context),
                "model": self._extract_model(llm_request),
                "agent_ctx": ctx,
                "invocation_id": ctx.get("invocation_id") or "",
            }

        latency_ms = int((time.time() - pending["started_at"]) * 1000)

        # Tag the model name so the server extractor detects google_adk.
        # The bare model id (e.g. "gemini-3.6-flash") becomes a suffix.
        raw_model = pending.get("model") or self._extract_model(llm_response) or "unknown"
        tagged_model = f"{_FRAMEWORK_TAG}:{raw_model}"

        agent_ctx = pending.get("agent_ctx") or self._extract_agent_context(callback_context)
        step_order = self._next_step_order(pending.get("invocation_id") or "")

        self._post_trace(
            input_messages=pending.get("input_messages") or [],
            output_message=self._extract_output(llm_response),
            model=tagged_model,
            latency_ms=latency_ms,
            token_count_input=self._extract_int(llm_response, ("usage_metadata", "prompt_token_count")),
            token_count_output=self._extract_int(llm_response, ("usage_metadata", "candidates_token_count")),
            agent_ctx=agent_ctx,
            step_order=step_order,
            adk_event_type="model_call",
        )

    def before_tool(self, tool: Any = None, args: Any = None, tool_context: Any = None, **kwargs: Any) -> None:
        """Stamp a start timestamp for tool execution; pairs with ``after_tool``.

        ADK 1.x point releases vary on whether ``before_tool_callback`` is
        called for every tool invocation, so this is a best-effort pairing.
        When ``before_tool`` does fire, ``after_tool`` looks up the
        recorded start time and emits a real ``latency_ms``; when it
        doesn't, ``after_tool`` falls back to the prior behavior
        (``latency_ms=0`` plus ``tool_latency_unavailable=True``).

        Never raises. Context-extraction failures degrade silently so
        the customer's ADK execution is never interrupted by tracing.
        """
        try:
            ctx = self._extract_agent_context(tool_context)
        except Exception as exc:
            print(f"[prismtrace adk] before_tool context extraction failed: {type(exc).__name__}")
            ctx = {"invocation_id": None, "agent_name": None, "agent_path": []}

        key = _tool_pending_key(tool, tool_context)
        with self._lock:
            if len(self._pending) >= _PENDING_MAX:
                evicted_key, _ = self._pending.popitem(last=False)
                print(f"[prismtrace adk] pending overflow; evicted oldest entry id={evicted_key}")
            self._pending[key] = {
                "started_at": time.time(),
                "tool_event": True,
                "agent_ctx": ctx,
                "invocation_id": ctx.get("invocation_id") or "",
            }

    def after_tool(self, tool: Any = None, args: Any = None, tool_response: Any = None, tool_context: Any = None, **kwargs: Any) -> None:
        """Capture a tool call as a separate trace tagged for ADK.

        Computes real ``latency_ms`` when ``before_tool`` was paired for
        this invocation; otherwise stamps 0 and records
        ``tool_latency_unavailable=True`` in metadata so consumers can
        distinguish "fast tool" from "no timing data".
        """
        tool_name = getattr(tool, "name", None) or (str(tool) if tool is not None else "unknown_tool")
        key = _tool_pending_key(tool, tool_context)
        with self._lock:
            pending = self._pending.pop(key, None)

        if pending is not None:
            latency_ms = int((time.time() - pending["started_at"]) * 1000)
            # Prefer the agent context captured at before_tool — it's the
            # state right before the tool fired, which is what we want.
            agent_ctx = pending.get("agent_ctx") or self._extract_agent_context(tool_context)
            latency_available = True
        else:
            latency_ms = 0
            agent_ctx = self._extract_agent_context(tool_context)
            latency_available = False

        step_order = self._next_step_order(agent_ctx.get("invocation_id") or "")

        extra_metadata: dict = {"tool_name": tool_name}
        if not latency_available:
            extra_metadata["tool_latency_unavailable"] = True

        self._post_trace(
            input_messages=[{"role": "tool_request", "content": str(args or {})[:8000]}],
            output_message=str(tool_response)[:8000],
            model=f"{_FRAMEWORK_TAG}:tool:{tool_name}",
            latency_ms=latency_ms,
            token_count_input=0,
            token_count_output=0,
            agent_ctx=agent_ctx,
            step_order=step_order,
            adk_event_type="tool_call",
            extra_metadata=extra_metadata,
        )

    # ------------------------------------------------------------------
    # Error capture
    # ------------------------------------------------------------------

    def record_model_error(self, exc: BaseException, callback_context: Any = None, **kwargs: Any) -> None:
        """Capture a model-level error as an error-status trace.

        ADK does not surface model errors through a callback today, so
        call this from a ``try / except`` around your model invocation
        (or from a custom runner) to keep PRISMtrace's error view honest.
        ``exc`` may be any exception instance; its class name lands in
        ``metadata.error_type`` and its (scrubbed) message in
        ``metadata.error_message``.
        """
        self._record_error(exc, callback_context, event_type="model_error")

    def record_tool_error(
        self,
        exc: BaseException,
        callback_context: Any = None,
        tool_name: Optional[str] = None,
        **kwargs: Any,
    ) -> None:
        """Capture a tool-execution error as an error-status trace.

        If ``before_tool`` was paired for this invocation, the recorded
        start time is consumed (so a later ``after_tool`` on the same
        key falls back to ``latency_ms=0`` rather than double-emitting)
        and real ``latency_ms`` is stamped on the error trace.
        """
        agent_ctx = self._safe_agent_context(callback_context)
        # Best-effort: pull a paired before_tool entry to compute real
        # tool latency. We can't reconstruct the exact pending-key
        # without the original tool/tool_context, so accept whichever
        # tool/tool_context the caller passed via kwargs.
        tool = kwargs.get("tool")
        tool_context = kwargs.get("tool_context") or callback_context
        pending_key = _tool_pending_key(tool, tool_context)
        with self._lock:
            pending = self._pending.pop(pending_key, None)
        latency_ms = 0
        if pending is not None and pending.get("tool_event"):
            latency_ms = int((time.time() - pending["started_at"]) * 1000)
            agent_ctx = pending.get("agent_ctx") or agent_ctx

        extra: dict = {}
        if tool_name:
            extra["tool_name"] = tool_name
        self._record_error(
            exc,
            callback_context,
            event_type="tool_error",
            latency_ms=latency_ms,
            agent_ctx_override=agent_ctx,
            extra_metadata=extra,
        )

    def record_runner_error(self, exc: BaseException, callback_context: Any = None, **kwargs: Any) -> None:
        """Capture a Runner-level / top-of-stack error as an error-status trace.

        Useful when an exception escapes the agent loop entirely (e.g.
        a transport error from ``Runner.run_async`` or an unhandled
        exception in your orchestration code).
        """
        self._record_error(exc, callback_context, event_type="runner_error")

    def _safe_agent_context(self, callback_context: Any) -> dict:
        """``_extract_agent_context`` with fail-open semantics for error paths.

        Error capture must never raise. If introspection of the callback
        context blows up — malformed object, partially-constructed agent
        chain — we still want to emit the error trace with the
        information we do have.
        """
        try:
            return self._extract_agent_context(callback_context)
        except Exception as exc:
            print(f"[prismtrace adk] agent-context extraction failed in error path: {type(exc).__name__}")
            return {
                "agent_name": None,
                "parent_agent_name": None,
                "agent_path": [],
                "invocation_id": None,
                "root_agent_name": None,
            }

    def _record_error(
        self,
        exc: BaseException,
        callback_context: Any,
        event_type: str,
        latency_ms: int = 0,
        agent_ctx_override: Optional[dict] = None,
        extra_metadata: Optional[dict] = None,
    ) -> None:
        """Shared error-trace emitter for the public ``record_*_error`` methods.

        Fail-open: any exception raised while assembling or POSTing the
        error trace is swallowed and printed (class name only, no
        secrets). The whole point is to capture customer-facing errors
        without piling another exception on top.
        """
        try:
            agent_ctx = agent_ctx_override or self._safe_agent_context(callback_context)
            error_type = type(exc).__name__ if exc is not None else "UnknownError"
            error_message = self._sanitize(exc)
            invocation_id = agent_ctx.get("invocation_id") or ""
            step_order = self._next_step_order(invocation_id)

            metadata: dict = {
                "status": "error",
                "error_type": error_type,
                "error_message": error_message,
            }
            if extra_metadata:
                metadata.update(extra_metadata)

            tool_name = (extra_metadata or {}).get("tool_name")
            model_tag = (
                f"{_FRAMEWORK_TAG}:{event_type}:{tool_name}"
                if tool_name
                else f"{_FRAMEWORK_TAG}:{event_type}"
            )

            self._post_trace(
                # Empty input + empty output flag the trace as an error
                # at the backend export layer (see backend/app/api/
                # traces.py — !output_message → status=error).
                input_messages=[],
                output_message="",
                model=model_tag,
                latency_ms=latency_ms,
                token_count_input=0,
                token_count_output=0,
                agent_ctx=agent_ctx,
                step_order=step_order,
                adk_event_type=event_type,
                extra_metadata=metadata,
            )
        except Exception as inner:
            print(f"[prismtrace adk] record_error itself failed: {type(inner).__name__}")

    def _sanitize(self, value: Any) -> str:
        """Instance-level wrapper around ``_scrub_secrets`` that also redacts
        the adapter's own ``api_key`` literal if it shows up in the value.

        Defense in depth: ``_SECRET_PATTERNS`` already catches common key
        prefixes, but a custom-format key (test fixture, BYO scheme) won't
        match the patterns. Redacting the literal handles that case too.
        """
        out = _scrub_secrets(value)
        if self.api_key and self.api_key in out:
            out = out.replace(self.api_key, "[REDACTED]")
        return out

    # ------------------------------------------------------------------
    # Hierarchy extraction
    # ------------------------------------------------------------------

    @staticmethod
    def _model_pending_key(agent_ctx: dict) -> tuple:
        """Key pairing before_model with after_model in ``_pending``.

        Both sides can compute it from their own ``CallbackContext``;
        no object identity is shared between the two callbacks (see
        ``before_model``). Namespaced with a ``"model"`` discriminator
        so it can't collide with tool keys.
        """
        return ("model", agent_ctx.get("invocation_id"), agent_ctx.get("agent_name"))

    def _next_step_order(self, invocation_id: str) -> int:
        with self._lock:
            cur = self._step_counters.get(invocation_id, 0)
            self._step_counters[invocation_id] = cur + 1
            return cur

    @staticmethod
    def _extract_agent_context(callback_context: Any) -> dict:
        """Pull (agent_name, parent_agent_name, agent_path, invocation_id, root_agent_name)
        from an ADK ``CallbackContext`` (or ``ToolContext``).

        ADK's context object exposes:
          - ``agent_name`` (or via ``_invocation_context.agent.name``)
          - ``invocation_id``
          - ``_invocation_context.agent`` — the active agent, whose
            ``.parent_agent`` chain walks up to the root.

        This walker is best-effort: missing attributes degrade to None /
        empty, never raise. Return shape is always populated so callers
        can stamp metadata unconditionally.
        """
        result = {
            "agent_name": None,
            "parent_agent_name": None,
            "agent_path": [],
            "invocation_id": None,
            "root_agent_name": None,
        }
        if callback_context is None:
            return result

        # Direct attributes — present on both CallbackContext and ToolContext.
        invocation_id = getattr(callback_context, "invocation_id", None)
        if invocation_id is not None:
            result["invocation_id"] = str(invocation_id)

        agent_name = getattr(callback_context, "agent_name", None)
        if agent_name is not None:
            result["agent_name"] = str(agent_name)

        # Reach into the invocation context to walk the parent chain.
        active_agent = None
        for attr in ("_invocation_context", "invocation_context"):
            ic = getattr(callback_context, attr, None)
            if ic is not None:
                active_agent = getattr(ic, "agent", None)
                if active_agent is not None:
                    break

        if active_agent is not None:
            # If we couldn't pull agent_name above, fall back to the agent.
            if not result["agent_name"]:
                result["agent_name"] = getattr(active_agent, "name", None)

            path: list[str] = []
            cur = active_agent
            depth = 0
            seen_ids: set[int] = set()
            while cur is not None and depth < 32:
                obj_id = id(cur)
                if obj_id in seen_ids:
                    break  # cycle guard
                seen_ids.add(obj_id)
                name = getattr(cur, "name", None)
                if name:
                    path.append(str(name))
                cur = getattr(cur, "parent_agent", None)
                depth += 1
            # Walk produced leaf → root; flip to root → leaf.
            path.reverse()
            result["agent_path"] = path
            if path:
                result["root_agent_name"] = path[0]
                if len(path) >= 2:
                    result["parent_agent_name"] = path[-2]
        elif result["agent_name"]:
            # No InvocationContext — single-agent flow. Make the path
            # the single-element list so downstream consumers can rely on
            # it being populated.
            result["agent_path"] = [result["agent_name"]]
            result["root_agent_name"] = result["agent_name"]

        return result

    @staticmethod
    def _node_id(agent_path: list[str], invocation_id: str) -> str:
        """Deterministic id for a node in the agent tree.

        Stable across re-runs of the same invocation, distinct across
        invocations, and identifies the agent's position in the hierarchy.
        """
        if not agent_path:
            return ""
        key = f"{invocation_id}:{'>'.join(agent_path)}"
        return hashlib.sha1(key.encode("utf-8")).hexdigest()[:16]

    # ------------------------------------------------------------------
    # Trace POST
    # ------------------------------------------------------------------

    def _post_trace(
        self,
        input_messages: list,
        output_message: str,
        model: str,
        latency_ms: int,
        token_count_input: int = 0,
        token_count_output: int = 0,
        agent_ctx: Optional[dict] = None,
        step_order: int = 0,
        adk_event_type: str = "model_call",
        extra_metadata: Optional[dict] = None,
    ) -> None:
        ctx = agent_ctx or {}
        agent_path = ctx.get("agent_path") or []
        invocation_id = ctx.get("invocation_id") or ""
        node_id = self._node_id(agent_path, invocation_id)
        parent_path = agent_path[:-1] if len(agent_path) > 1 else []
        parent_node_id = self._node_id(parent_path, invocation_id) if parent_path else None

        # The trajectory's display agent_name comes from this field. Prefer
        # the per-call agent name (so sub-agent traces show the sub-agent),
        # fall back to the adapter-level default (so the trajectory still
        # has a sensible name when ctx walking failed).
        display_agent_name = ctx.get("agent_name") or self.agent_name
        session_id = self._session_for(invocation_id)

        metadata = {
            # Existing fields — keep these names stable; older readers
            # depend on them.
            "framework": "google_adk",
            "agent_name": display_agent_name,
            "agent_id": display_agent_name,
            "source": "google-adk-sdk",
            "session_id": session_id,
            "step_order": step_order,
            # Backwards-compatible alias for the old "adk_event" key
            # introduced in PR #17.
            "adk_event": adk_event_type,
            "adk_event_type": adk_event_type,
            # Hierarchy fields — new in this release.
            "parent_agent_id": ctx.get("parent_agent_name"),
            "parent_agent_name": ctx.get("parent_agent_name"),
            "agent_path": agent_path,
            "root_agent_name": ctx.get("root_agent_name"),
            "invocation_id": invocation_id,
            "node_id": node_id,
            "parent_node_id": parent_node_id,
        }
        if extra_metadata:
            metadata.update(extra_metadata)

        payload = {
            "project_id": self.project_id,
            "model": model,
            "input_messages": input_messages,
            "output_message": output_message,
            "latency_ms": latency_ms,
            "token_count_input": token_count_input or 0,
            "token_count_output": token_count_output or 0,
            "session_id": session_id,
            "metadata": metadata,
        }
        try:
            self._http.post(f"{self.endpoint}/api/traces", json=payload)
        except Exception as exc:
            # Tracing must never break the user's agent flow. Print and
            # carry on — same fail-open policy as the LangChain handler.
            # Never log the API key; httpx error reprs may include the
            # request URL but not headers.
            print(f"[prismtrace adk] trace post failed: {type(exc).__name__}")

    # ------------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------------

    @staticmethod
    def _extract_input_messages(llm_request: Any, callback_context: Any) -> list:
        """Best-effort extract conversation history from ADK objects.

        ADK's ``LlmRequest`` shape has shifted across versions; we probe a
        few likely attribute paths and fall back to a single user message.
        """
        if llm_request is None:
            return []
        for path in (("contents",), ("messages",), ("input", "contents")):
            obj = llm_request
            for attr in path:
                obj = getattr(obj, attr, None)
                if obj is None:
                    break
            if obj is not None:
                try:
                    return [
                        {
                            "role": getattr(m, "role", "user") or "user",
                            "content": PRISMtraceADKAdapter._content_text(m)[:8000],
                        }
                        for m in obj
                    ]
                except Exception:
                    pass
        return []

    @staticmethod
    def _content_text(message: Any) -> str:
        """Flatten a genai ``Content`` (role + parts) into plain text.

        Real ADK requests carry ``types.Content`` objects whose text
        lives in ``parts[i].text``; non-text parts (function calls,
        inline data) are skipped. Falls back to a ``.text`` attribute,
        then to ``str()`` so unknown shapes still capture something.
        """
        parts = getattr(message, "parts", None)
        if parts:
            texts = [t for t in (getattr(p, "text", None) for p in parts) if t]
            if texts:
                return "\n".join(str(t) for t in texts)
        text = getattr(message, "text", None)
        if text is not None:
            return str(text)
        return str(message)

    @staticmethod
    def _extract_model(obj: Any) -> Optional[str]:
        # "model_version" is where ADK's LlmResponse reports the model id;
        # LlmRequest uses plain "model".
        if obj is None:
            return None
        for attr in ("model", "model_name", "model_id", "model_version"):
            v = getattr(obj, attr, None)
            if v:
                return str(v)
        return None

    @staticmethod
    def _extract_output(llm_response: Any) -> str:
        if llm_response is None:
            return ""
        for path in (("text",), ("content", "parts", 0, "text"), ("candidates", 0, "content", "parts", 0, "text")):
            obj: Any = llm_response
            for step in path:
                try:
                    obj = obj[step] if isinstance(step, int) else getattr(obj, step, None)
                except (KeyError, IndexError, AttributeError):
                    obj = None
                if obj is None:
                    break
            if obj is not None:
                return str(obj)[:16000]
        return str(llm_response)[:16000]

    @staticmethod
    def _extract_int(obj: Any, path: tuple) -> int:
        cur: Any = obj
        for step in path:
            cur = getattr(cur, step, None)
            if cur is None:
                return 0
        try:
            return int(cur)
        except (TypeError, ValueError):
            return 0

    # ------------------------------------------------------------------
    # Lifecycle
    # ------------------------------------------------------------------

    def close(self) -> None:
        """Release the HTTP connection pool opened in the constructor.

        Idempotent. Also available as a context manager.
        """
        if self._closed:
            return
        self._closed = True
        try:
            self._http.close()
        except Exception:
            pass

    def __enter__(self) -> "PRISMtraceADKAdapter":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.close()
        return False
